const trigger = $('Normalize Input').first().json;
const checkIn = trigger.check_in;
const checkOut = trigger.check_out;
const roomTypeFilter = trigger.room_type;

if (!checkIn || !checkOut) {
  return [{
    json: {
      error: 'missing_dates',
      message: 'check_in and check_out are both required, each in YYYY-MM-DD format. Ask the guest for both dates and call this tool again.'
    }
  }];
}

const rooms = $('Get Rooms').all().map(item => item.json);
const bookings = $('Get Bookings').all().map(item => item.json);

const results = [];
for (const room of rooms) {
  if (roomTypeFilter && room.room_type !== roomTypeFilter) continue;
  let overlapping = 0;
  for (const b of bookings) {
    if (b.room_type !== room.room_type) continue;
    const bIn = b.check_in;
    const bOut = b.check_out;
    const overlaps = !(bOut <= checkIn || bIn >= checkOut);
    if (overlaps) overlapping++;
  }
  const roomsLeft = room.total_rooms - overlapping;
  results.push({
    room_type: room.room_type,
    rate: room.rate,
    amenities: room.amenities,
    rooms_left: roomsLeft,
    available: roomsLeft > 0
  });
}

return [{
  json: {
    check_in: checkIn,
    check_out: checkOut,
    available: results.some(r => r.available),
    rooms: results
  }
}];

const raw = $input.item.json;
const SHARED_SECRET = 'YOUR_SHARED_SECRET';

let body;
if (raw.headers && raw.body !== undefined) {
  // Came in via the public Webhook (e.g. ElevenLabs) - verify the shared secret.
  const providedKey = raw.headers['x-api-key'] || raw.headers['X-Api-Key'];
  if (providedKey !== SHARED_SECRET) {
    throw new Error('Unauthorized: missing or invalid x-api-key header');
  }
  body = raw.body;
} else {
  // Came in via Execute Workflow Trigger (the n8n chat agent) - already trusted internally.
  body = raw;
}

return [{
  json: {
    check_in: body.check_in,
    check_out: body.check_out,
    room_type: body.room_type
  }
}];
